style.css:
@-moz-document domain("youtube.com") {
/* Background Image */
    body {
        background: url("https://i.imgur.com/your-cinnamoroll-image.png") no-repeat center center fixed;
        background-size: cover;
        font-family: 'Comic Sans MS', cursive, sans-serif;
    }
    
    /* Header & Search Bar */
    #masthead-container {
        background: linear-gradient(135deg, #ffdde1, #ee9ca7, #f4a7c4);
        border-bottom: 3px solid #ff69b4;
        box-shadow: 0px 5px 10px rgba(0, 0, 0, 0.1);
    }
    #search-input {
        background: #fff;
        border-radius: 30px;
        border: 2px solid #f4a7c4;
        padding-left: 15px;
        transition: all 0.3s ease;
    }
    #search-input:focus {
        border-color: #ff69b4;
        outline: none;
    }
    
    /* Sidebar */
    #guide-content {
        background: rgba(255, 240, 245, 0.8);
        border-radius: 20px;
        padding: 15px;
        box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.1);
    }
    
    /* Video Titles & Links */
    a.ytd-video-renderer, a.ytd-grid-video-renderer {
        color: #ff69b4 !important;
        font-family: 'Comic Sans MS', cursive;
        text-shadow: 1px 1px 2px rgba(255, 255, 255, 0.7);
        transition: color 0.3s ease, text-shadow 0.3s ease;
    }
    a.ytd-video-renderer:hover, a.ytd-grid-video-renderer:hover {
        color: #ff1493 !important;
        text-shadow: 2px 2px 4px rgba(255, 255, 255, 0.9);
    }
    
    /* Buttons */
    tp-yt-paper-button {
        background: linear-gradient(145deg, #ffb6c1, #ff69b4) !important;
        border-radius: 15px !important;
        color: white !important;
        font-weight: bold !important;
        box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.1);
        padding: 8px 15px;
        transition: background 0.3s ease, transform 0.2s ease;
    }
    tp-yt-paper-button:hover {
        background: linear-gradient(145deg, #ff69b4, #ff1493) !important;
        transform: scale(1.05);
    }
    
    /* Profile Pictures */
    #avatar, img.yt-img-shadow {
        border-radius: 50% !important;
        border: 4px solid #ffb6c1 !important;
        box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.1);
    }
    
    /* Floating Action Button */
    ytd-app div#content ytd-masthead div#avatar-btn {
        background: #ff69b4 !important;
        border-radius: 50% !important;
        padding: 10px;
        box-shadow: 0px 5px 15px rgba(0, 0, 0, 0.1);
    }
    ytd-app div#content ytd-masthead div#avatar-btn:hover {
        background: #ff1493 !important;
        transform: scale(1.1);
    }
    
    /* Playlists */
    ytd-playlist-video-renderer {
        border-bottom: 1px solid #f4a7c4;
        padding: 10px 0;
    }
    ytd-playlist-video-renderer:hover {
        background-color: rgba(255, 240, 245, 0.8);
    }
}
